<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import VacancyForm from '@/components/industry/VacancyForm.vue';
import TablePagination from '@/components/admin/TablePagination.vue';
import type { Company, Vacancy } from '@/types/industry';
import type { Paginated } from '@/types/admin';
const props = defineProps<{ company: Company | null; vacancies: Paginated<Vacancy> | null; careers: { id: number; title: string }[] }>();
const companyOpen = ref(!props.company);
const open = ref(false);
const editing = ref<Vacancy | null>(null);
const form = useForm({ name: props.company?.name || '', industry: props.company?.industry || '', location: props.company?.location || '', description: props.company?.description || '', website: props.company?.website || '' });
function edit(vacancy: Vacancy | null) { editing.value = vacancy; open.value = true; }
</script>
<template><p v-if="company?.location_is_approximate" class="mb-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Company map pins use a randomly assigned demo city in your state. Vacancies share this company pin.</p><Head title="Industry workspace" /><p class="text-xs font-bold tracking-widest text-teal-700 uppercase">Connect skills with opportunity</p><h1 class="mt-3 text-3xl font-semibold">{{ company?.name || 'Welcome to your employer workspace' }}</h1><p class="mt-3 text-slate-500">Manage your company profile and open opportunities for TVET talent.</p><div class="my-6 flex flex-wrap items-center justify-between gap-4 rounded-xl border border-slate-200 bg-white p-5"><div><span class="font-semibold" :class="company?.is_approved ? 'text-teal-700' : 'text-amber-700'">{{ company?.is_approved ? 'Company approved' : company ? 'Awaiting admin approval' : 'Complete your company profile' }}</span><p class="mt-1 text-sm text-slate-500">{{ company?.is_approved ? 'You can publish vacancies.' : 'Save drafts while your company is being reviewed.' }}</p></div><button class="text-sm font-semibold text-teal-700" @click="companyOpen = !companyOpen">{{ companyOpen ? 'Hide profile' : 'Edit company profile' }}</button></div><form v-if="companyOpen" class="mb-8 space-y-4 rounded-xl border border-slate-200 bg-white p-7" @submit.prevent="form.put('/industry/company', { onSuccess: () => companyOpen = false })"><h2 class="text-xl font-semibold">Company profile</h2><p class="text-sm text-slate-500">Changes to company details require admin approval again.</p><div class="grid gap-4 md:grid-cols-2"><label v-for="key in (['name','industry','location','website'] as const)" :key="key" class="text-sm font-medium capitalize">{{ key }}<input v-model="form[key]" :required="key !== 'website'" :type="key === 'website' ? 'url' : 'text'" class="mt-2 block w-full rounded-lg border p-3" /><span class="text-red-600">{{ form.errors[key] }}</span></label></div><label class="block text-sm font-medium">About the company<textarea v-model="form.description" required rows="3" class="mt-2 block w-full rounded-lg border p-3" /><span class="text-red-600">{{ form.errors.description }}</span></label><button :disabled="form.processing" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50">Save company profile</button></form><div class="flex items-center justify-between"><h2 class="text-2xl font-semibold">Your vacancies</h2><button v-if="company" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-semibold text-white" @click="edit(null)">+ Create vacancy</button></div><VacancyForm v-if="open" :key="editing?.id || 'new'" :vacancy="editing" :careers="careers" :approved="!!company?.is_approved" @close="open = false" /><div class="mt-6 overflow-hidden rounded-xl border border-slate-200 bg-white"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-100 text-xs text-slate-500 uppercase"><tr><th class="p-5">Opening</th><th class="p-5">Status</th><th class="p-5">Closes</th><th class="p-5">Manage</th></tr></thead><tbody><tr v-for="vacancy in vacancies?.data || []" :key="vacancy.id" class="border-t border-slate-100"><td class="p-5"><p class="font-semibold">{{ vacancy.title }}</p><p class="mt-1 text-slate-500">{{ vacancy.location }} · {{ vacancy.type }}</p></td><td class="p-5 capitalize">{{ vacancy.status }}</td><td class="p-5">{{ vacancy.closing_date.slice(0,10) }}</td><td class="p-5"><button class="font-semibold text-teal-700" @click="edit(vacancy)">Edit</button><Link :href="`/industry/vacancies/${vacancy.id}/applicants`" class="ml-4 font-semibold text-teal-700">Applicants ({{ vacancy.applications_count ?? 0 }})</Link></td></tr><tr v-if="!vacancies?.data.length"><td colspan="4" class="p-10 text-center text-slate-500">No openings yet. Complete your company profile to create one.</td></tr></tbody></table></div><TablePagination v-if="vacancies" :current="vacancies.current_page" :last="vacancies.last_page" :total="vacancies.total" :previous="vacancies.prev_page_url" :next="vacancies.next_page_url" /></div></template>
